import{_ as t,o as a,c as _,a4 as s}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"山东青岛：田头冷链提速　破解流通堵点2026-05-26","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"山东青岛：田头冷链提速　破解流通堵点2026-05-26","date":"2026-05-26T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://scs.moa.gov.cn/gzdt/202605/t20260528_6484508.htm","summary":"农民日报全媒体记者　郝凌峰\\n农产品出村进城,冷链物流是关键一环。近日,山东省青岛市农业农村局、市财政局联合印发农产品产地冷藏保鲜设施建设相关方案,以“田头市场+新型农业经营主体+农户”模式为抓手,加快布局通风贮藏库、机械冷库、气调贮藏库等设施,向产业重点镇、中心村聚集,着力破解鲜活农产品流通“最先一公里”难题。\\n...\\n","contentHash":"e1c3b28a01adfab9ba704fc2acb94645","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-05-26-山东青岛-田头冷链提速-破解流通堵点.md","filePath":"policies/2026-05-26-山东青岛-田头冷链提速-破解流通堵点.md"}'),r={name:"policies/2026-05-26-山东青岛-田头冷链提速-破解流通堵点.md"};function o(p,e,n,c,l,i){return a(),_("div",null,[...e[0]||(e[0]=[s('<h1 id="山东青岛-田头冷链提速-破解流通堵点2026-05-26" tabindex="-1">山东青岛：田头冷链提速　破解流通堵点2026-05-26 <a class="header-anchor" href="#山东青岛-田头冷链提速-破解流通堵点2026-05-26" aria-label="Permalink to &quot;山东青岛：田头冷链提速　破解流通堵点2026-05-26&quot;">​</a></h1><blockquote><p>来源: <a href="https://scs.moa.gov.cn/gzdt/202605/t20260528_6484508.htm" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-05-26 摘要: 农民日报全媒体记者　郝凌峰 农产品出村进城,冷链物流是关键一环。近日,山东省青岛市农业农村局、市财政局联合印发农产品产地冷藏保鲜设施建设相关方案,以“田头市场+新型农业经营主体+农户”模式为抓手,加快布局通风贮藏库、机械冷库、气调贮藏库等设施,向产业重点镇、中心村聚集,着力破解鲜活农产品流通“最先一公里”难题。 ...</p></blockquote><p>农产品出村进城,冷链物流是关键一环。近日,山东省青岛市农业农村局、市财政局联合印发农产品产地冷藏保鲜设施建设相关方案,以“田头市场+新型农业经营主体+农户”模式为抓手,加快布局通风贮藏库、机械冷库、气调贮藏库等设施,向产业重点镇、中心村聚集,着力破解鲜活农产品流通“最先一公里”难题。</p><p>方案明确,设施建设聚焦蔬菜、水果两大品类,兼顾地方优势特色品种,经营主体可按需自选库型与规模,突出产地预冷、分拣包装、冷藏保鲜等核心功能,实现错峰销售、提质增效。业内人士表示,推进田头冷藏保鲜设施建设,可有效降低果蔬产后损耗、延长销售周期、提升产品附加值,让好生鲜卖出好价钱,真正把收益留在田间地头。</p><p>作为人口超千万的沿海中心城市,青岛“菜篮子”保供分量十足。全市扎实推进“36111”稳产保供工程,构建年产600万吨蔬菜、100万吨肉蛋奶的多元供给体系,自给率超60%。青岛市商务局加大货源统筹力度,已完成1万余吨蔬菜、猪肉政府储备收储,夯实市场“稳定器”。据监测,当前全市粮食价格整体平稳,肉类价格小幅波动,鸡蛋价格持平,蔬菜批发价格受季节因素呈现结构性分化。</p><p>热闹的产销景象背后,流通环节短板依然突出。长期以来,青岛产地冷链设施不足、分布不均,叶菜类农产品从田间到批发市场,损耗率普遍在20%至30%,远高于发达国家5%至10%的水平。不少种植主体反映,冷库用地审批难、运营成本偏高,中小农户难以独立承担冷链投入。作为胶东重要蔬菜集散地,莱西东庄头蔬菜批发市场日均交易量稳定在300万公斤以上,但周边产地预冷设施配套不足,上市旺季常出现“产地热、市场冷”的错位现象,新鲜果蔬难以及时预冷入库,影响品质与效益。</p><p>为破解堵点,青岛把田头市场与冷藏保鲜设施一体化推进,推动冷链资源向优势产区集中、向田头聚集,构建就近预冷、就地仓储、快捷分销的流通新模式。依托政策引导与财政补贴支持,家庭农场、农民合作社等经营主体加快补冷链、建库房,推动“采收—预冷—分拣—仓储—配送”无缝衔接,从源头减少损耗、稳住品质。</p><p>与此同时,中国·山东“菜篮子”高质量发展指数正式发布,为全省农产品产业发展提供数字化观测标尺。专家指出,青岛作为山东重要消费城市和港口枢纽,既要守牢本地供应底线,也要发挥口岸优势做强农产品进出口贸易。完善产地冷藏保鲜设施,既是补齐流通短板的民生工程,也是提升“青岛农品”竞争力、畅通国内国际双循环的关键支撑。</p><p>小小冷库连着田间地头、系着万家餐桌。随着一批田头冷藏保鲜设施加快落地,青岛正以冷链补短板、以模式畅流通,推动生鲜农产品少损耗、多增值、稳供应,让田间新鲜直达餐桌,让农民增收更有底气,为乡村产业振兴和“菜篮子”高质量发展注入强劲动能。</p><p><a href="https://scs.moa.gov.cn/gzdt/202605/t20260528_6484508.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',10)])])}const m=t(r,[["render",o]]);export{f as __pageData,m as default};
